      .from("canevas")
      .select("id", { count: "exact", head: true })
      .eq("sector", sector)
      .eq("category", category)
      .neq("title", "-");

    if (error) throw error;
    return count || 0;
  };

  const countRealCanevasInSubCategory = async (sector, category, subCategory) => {
    const { count, error } = await supabase
      .from("canevas")
      .select("id", { count: "exact", head: true })
