  const undoLastCanevasAction = async () => {
    try {
      setIsUndoing(true);
      setUndoMsg("");

      const { data: prev, error: prevErr } = await supabase.rpc("preview_last_canevas_history_action", {
        p_sector: adminSector,
      });

      if (prevErr) {
        alert(`❌ Preview impossible.\n${prevErr.message}`);
        return;
      }
      if (!prev?.ok) {
        alert(prev?.message || "Aucune action à annuler.");
        return;
      }

      const ok = window.confirm(`${prev.message}\n\nConfirmer l’annulation ?`);
      if (!ok) return;

      const { data, error } = await supabase.rpc("undo_last_canevas_history_action", {
        p_sector: adminSector,
      });

      if (error) {
        alert(`❌ Annulation échouée.\n${error.message}`);
        return;
      }
      if (!data?.ok) {
        alert(data?.message || "Aucune action à annuler.");
        return;
      }

      await fetchCategories();
      if (selectedCategory) await fetchSubCategories();
      if (selectedCategory && selectedSubCategory) await fetchCanevas();

      setUndoMsg("✅ Dernière action annulée.");
      setTimeout(() => setUndoMsg(""), 2600);
    } finally {
      setIsUndoing(false);
    }
  };

