      const ok = requireTypeSUPPRIMER(
        `⚠️ Cette catégorie contient ${realCount} canevas réels.\n\nTape SUPPRIMER pour confirmer la suppression.`
      );
      if (!ok) return;

      await postgrestDelete({
        table: "canevas",
        filters: { sector: adminSector, category: cat },
